export type Product = { id: string; name: string; price: number; featured: boolean; special?: { until: string; price: number } };

export const catalog: Product[] = [
  { id: 'mug', name: 'Harbor Mug', price: 18, featured: true },
  { id: 'tote', name: 'Canvas Tote', price: 32, featured: true },
  { id: 'lamp', name: 'Chart Lamp', price: 54, featured: true },
  { id: 'rope', name: 'Dock Rope Coaster', price: 9, featured: false, special: { until: '2026-04-19', price: 6 } },
];

export function featured(): Product[] {
  return catalog.filter(product => product.featured);
}

/** The product on special this week, if its offer has not ended. */
export function weeklySpecial(today: Date): Product | undefined {
  return catalog.find(product => product.special && new Date(product.special.until) >= today);
}

import { weeklySpecial } from '../api/products';

export function WeeklySpecial({ today }: { today: Date }) {
  const product = weeklySpecial(today);
  if (!product?.special) return null;
  return (
    <article className="card special">
      <p className="kicker">This week only</p>
      <strong>{product.name}</strong>
      <p className="price"><s>${product.price}</s> ${product.special.price}</p>
    </article>
  );
}

